using System;using System.IO;using System.Collections;using UnityEngine;using UnityEditor;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public class LungeWallProbe:MonoBehaviour{
 string folder;public static object Begin(string folder){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Lunge wall safety probe").AddComponent<LungeWallProbe>();p.folder=folder;p.StartCoroutine(p.Go());return true;}
 IEnumerator Go(){var t=HorrorTuning.Current;var root=new GameObject("Wall probe root");var kit=new ScareKit(root.transform);var feet=new Vector3(0,0,-6.5f);var eye=feet+Vector3.up*1.65f;var c=new ScareSequenceState(t);c.Begin(3,feet+Vector3.forward*.75f);for(int i=0;i<200&&c.Beat!=ScareBeat.Escape;i++)c.Tick(.1f,true,true,0,0);kit.Present(c,eye);var r=root.transform.Find("Scripted scare kit/Nightmare child").GetComponent<Renderer>();var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.name="Test wall between catch and lunge origin";wall.transform.position=feet+Vector3.forward*1.4f+Vector3.up;wall.transform.localScale=new Vector3(1.5f,2,.1f);Physics.SyncTransforms();c.Catch(1,feet);kit.Present(c,eye);yield return new WaitForSeconds(.12f);kit.Present(c,eye);bool ok=!r.enabled;File.WriteAllText(folder+"/checks.txt",(ok?"PASS ":"FAIL ")+"Blocked lunge is suppressed rather than appearing through a wall\n");File.WriteAllText(folder+"/result.json","{\"passed\":"+(ok?"true":"false")+"}");kit.Dispose();Destroy(wall);Destroy(root);Destroy(gameObject);}
}
